template <typename T, size_t N>
constexpr size_t array_size(const T (&)[N]) {
  return N;
}

int main() {
  int arr[10];
  constexpr size_t size = array_size(arr); // Compile-time calculation
  std::cout << size << std::endl; // Output: 10
  return 0;
}
