#include <iostream>
#include <array>
template <typename T, size_t N>
constexpr T factorial(size_t n) {
  return (n == 0) ? 1 : n * factorial<T,N>(n - 1);
}
int main() {
  constexpr size_t size = 5;
  constexpr int result = factorial<int, 100>(size); // Compile-time factorial calculation
  std::cout << "Factorial of " << size << " is " << result << std::endl; // Output: 120
  std::array<int, factorial<int, 100>(size)> arr; // array size determined at compile time.
  return 0;
}
